// doble clic en el stage-wrap (fuera de tray) alterna "solo pizza"
document.querySelector('.stage-wrap').addEventListener('dblclick',()=>document.body.classList.toggle('solo'));

// ---------- teclado ----------
window.addEventListener('keydown',e=>{
  if(e.target.tagName==='INPUT') return;
  const k=e.key.toLowerCase();
  if((e.ctrlKey||e.metaKey)&&k==='z'){ e.preventDefault(); e.shiftKey?redo():undo(); return; }
  if((e.ctrlKey||e.metaKey)&&k==='y'){ e.preventDefault(); redo(); return; }
  if(e.key==='Escape' && placing){ unloadIngredient(); return; }
  if(!selected) return;
  if(k==='r'){ act(e.shiftKey?'rotL':'rotR'); }
  else if(k===']'||k==='+'||k==='='){ act('up'); }
  else if(k==='['||k==='-'){ act('down'); }
  else if(k==='f'){ act('flip'); }
  else if(k==='c'){ chop(selected, e.shiftKey?-1:1); }
  else if(k==='d'){ e.preventDefault(); act('dup'); }
  else if(k==='delete'||k==='backspace'){ e.preventDefault(); act('del'); }
  else if(k==='escape'){ select(null); }
});

// ---------- resize ----------
let rz; window.addEventListener('resize',()=>{ clearTimeout(rz); rz=setTimeout(()=>{ renderAll(); },120); });

// ---------- exportar PNG ----------
function _isIOS(){ return /iP(hone|ad|od)/.test(navigator.userAgent) || (navigator.platform==='MacIntel' && navigator.maxTouchPoints>1); }
function _dataURLtoBlob(u){ const p=u.split(','); const mime=(p[0].match(/:(.*?);/)||[])[1]||'image/png'; const bin=atob(p[1]); const n=bin.length, a=new Uint8Array(n); for(let i=0;i<n;i++)a[i]=bin.charCodeAt(i); return new Blob([a],{type:mime}); }
function _showSaveSheet(url, filename){
  let ov=document.getElementById('saveSheet');
  if(!ov){
    ov=document.createElement('div'); ov.id='saveSheet';
    ov.style.cssText='position:fixed;inset:0;z-index:200;background:rgba(20,12,6,.92);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;padding:20px';
    ov.innerHTML='<img alt="" style="max-width:92%;max-height:62vh;border-radius:12px;box-shadow:0 12px 40px rgba(0,0,0,.5)"><p style="color:#fff;font-family:sans-serif;font-size:15px;line-height:1.4;text-align:center;margin:0;max-width:330px">Manten\u00e9 presionada la imagen y eleg\u00ed <b>Guardar en Fotos</b> \u2014 o tocá Compartir.</p><div style="display:flex;gap:10px"><button class="sh" style="padding:11px 20px;border:0;border-radius:10px;background:#fff;color:#111;font-family:sans-serif;font-size:15px;font-weight:600">Compartir / Guardar</button><button class="cl" style="padding:11px 20px;border:1px solid rgba(255,255,255,.5);border-radius:10px;background:transparent;color:#fff;font-family:sans-serif;font-size:15px">Cerrar</button></div>';
    document.body.appendChild(ov);
    ov.querySelector('.cl').onclick=()=>ov.remove();
    ov.addEventListener('click',e=>{ if(e.target===ov) ov.remove(); });
    ov.querySelector('.sh').onclick=async()=>{ try{ const f=new File([_dataURLtoBlob(ov.__url)], ov.__fn||'pizza.png', {type:'image/png'}); if(navigator.canShare && navigator.canShare({files:[f]})){ await navigator.share({files:[f]}); } else if(navigator.share){ await navigator.share({title:ov.__fn||'Pizza'}); } }catch(e){} };
  }
  ov.__url=url; ov.__fn=filename; ov.querySelector('img').src=url;
}
function exportPNG(){
  const sz=stageSize();
  const sizeK=(fmtDef().wcm||27)/27;                    // la pizza sale proporcional a su tamaño real
  const S=Math.round((900*sizeK/sz)*1000)/1000;         // regular ≈ 900px, NY ≈ 2000px, etc.
  const W=Math.round(sz*S);
  const H=Math.round(W/fmtAspect());                    // alto según el formato (elipse en plancha)
  const cv=document.createElement('canvas'); cv.width=W; cv.height=H;
  const c=cv.getContext('2d'); c.imageSmoothingEnabled=false;
  const m=Math.max(W,H)*0.02;
  const cx=W/2, cy=H/2, R=Math.min(W,H)/2 - m;
  // masa: sprite del estilo (Napolitana/NY/Molde/Plancha, cruda o cocida)
  if(baseImg.complete && baseImg.naturalWidth) c.drawImage(baseImg,0,0,W,H);
  // salsa / base de color (según el estilo, con forma de la pizza)
  const si=sauceInsetFor(), _db=doughBoxFor(), _dw=W*(_db.x1-_db.x0), _dh=H*(_db.y1-_db.y0);
  const srx=(_dw/2)*(1-2*si.x), sry=(_dh/2)*(1-2*si.y);
  paintBaseAll(c, cx, cy, srx, sry);
  // toppings
  items.sort((a,b)=>a.z-b.z).forEach(it=>{
    const s=stateSprite(it); const img=imgFor(s.uri);
    const w=s.w*PX*scaleFor(it.sid)*fmtScale()*it.scl*(sz/REF)*S, h=s.h*PX*scaleFor(it.sid)*fmtScale()*it.scl*(sz/REF)*S;
    c.save(); c.globalAlpha=opacityOf(it.sid); c.translate(it.fx*W,it.fy*H); c.rotate(it.rot*Math.PI/180); c.scale(it.flip?-1:1,1);
    try{ c.drawImage(img,-w/2,-h/2,w,h);}catch(e){}
    c.restore();
  });
  drawDrizzles(c, cx, cy, R, activeDrizzles);
  cv.toBlob(b=>{
    const a=document.createElement('a'); a.href=URL.createObjectURL(b);
    const _nm=(document.getElementById('pizzaName').value||'').trim();
    const _slug=_nm ? _nm.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'') : '';
    a.download=(_slug?('pizza-'+_slug):'pizza-arrabbiata')+'.png';
    if(_isIOS()){ _showSaveSheet(cv.toDataURL('image/png'), a.download); } else { a.click(); }
    setTimeout(()=>URL.revokeObjectURL(a.href),1000);
  });
  toast('PNG exportado');
}

// ---------- toast ----------
let tt; function toast(m){ const t=document.getElementById('toast'); t.textContent=m; t.classList.add('show'); clearTimeout(tt); tt=setTimeout(()=>t.classList.remove('show'),1800); }

