// ---------- init ----------
function applyLibrary(ings){
  SPRITES.length=0;
  for(const k in STATES) delete STATES[k];
  for(const k in spriteById) delete spriteById[k];
  ings.forEach(i=>{
    const e=i.states&&i.states.entero; if(!e) return;
    const sp={id:i.id,name:i.name,cat:i.cat||'otros',w:e.w,h:e.h,uri:e.uri};
    if(i.scale&&i.scale!==1) sp.scl=i.scale;
    if(i.opacity!=null && i.opacity!==1) sp.op=i.opacity;
    SPRITES.push(sp); spriteById[i.id]=sp;
    const im=new Image(); im.src=e.uri; imgCache[sp.id]=im;
    const stt={}; ['mitad','picado'].forEach(k=>{ if(i.states[k]){ stt[k]=i.states[k]; imgFor(i.states[k].uri); } });
    if(Object.keys(stt).length) STATES[i.id]=stt;
  });
  activeSid = SPRITES.length ? SPRITES[0].id : null;
}
document.getElementById('btnLoadLib').addEventListener('click',()=>document.getElementById('fileLib').click());
document.getElementById('fileLib').addEventListener('change',function(){
  const f=this.files[0]; this.value=''; if(!f) return;
  const r=new FileReader();
  r.onload=()=>{ try{ const d=JSON.parse(r.result); if(!d.ingredients||!d.ingredients.length) throw 0;
    applyLibrary(d.ingredients); applyDrizzles(d.drizzles); applyBases(d.bases); buildCatBar(); buildTray();
    try{ localStorage.setItem('rrbb_pizza_lib', r.result); }catch(e){}
    toast(`Biblioteca cargada (${d.ingredients.length} ingredientes)`);
  }catch(e){ toast('JSON inválido'); } };
  r.readAsText(f);
});
(async function boot(){
  let loaded=false;
  try{
    const r=await fetch('ingredients.json',{cache:'no-store'});
    if(r.ok){ const d=await r.json(); if(d&&Array.isArray(d.ingredients)&&d.ingredients.length){ applyLibrary(d.ingredients); applyDrizzles(d.drizzles); applyBases(d.bases); if(d.styles) applyStyles(d.styles); loaded=true; } }
  }catch(e){}
  if(!loaded){ try{ const s=localStorage.getItem('rrbb_pizza_lib'); if(s){ const d=JSON.parse(s); if(d.ingredients&&d.ingredients.length){ applyLibrary(d.ingredients); applyDrizzles(d.drizzles); applyBases(d.bases); if(d.styles) applyStyles(d.styles); } } }catch(e){} }
  buildCatBar(); buildTray(); setBake(1); setBase(curBase); setFmt(curFmt, true); syncSizeButtons();
})();
</script>

<!-- ============ Exportador social ============ -->
<div class="expmask" id="expMask">
