<script>
/* ============================================================
   Exportador social Arrabbiata — Feed / Historia
   Composición: [ribbon] · pizza · nombre · caja de ingredientes
   ============================================================ */
(function(){
  "use strict";
  const FB64="";
  const FF='ArrbbtTipo, "DM Serif Display", Georgia, serif';
  let fontOK=false;
  (async()=>{ try{
    const f=new FontFace('ArrbbtTipo','url(data:font/ttf;base64,'+FB64+')');
    await f.load(); document.fonts.add(f); fontOK=true; if(mask.classList.contains('on')) draw();
  }catch(e){ console.warn('ArrbbtTipo no cargó',e); } })();

  const FORMATS={
    feed:  {w:1080,h:1080},
    feed45:{w:1080,h:1350},
    story: {w:1080,h:1920}
  };
  const BASE_LABEL={tomate:'Salsa de tomate',pesto:'Pesto',blanca:'Base blanca',picante:'Salsa picante'};

  // ---- refs ----
  const mask=document.getElementById('expMask');
  const cv=document.getElementById('expCanvas');
  const listEl=document.getElementById('expList');
  const nameInput=document.getElementById('expName');
  const ribOn=document.getElementById('expRibbonOn');
  const ribTxt=document.getElementById('expRibbonTxt');
  const pizzaNameEl=document.getElementById('pizzaName');

  // ---- estado del exportador ----
  let fmt='feed';
  const meta={};                 // sid -> {include, label}
  let order=[];                  // sids reordenables (sin muzza)
  let drizOrder=[];              // ids de salsas (drizzles) activas, en orden
  let hasMuzza=false;
  let baseInc=true, baseLabel='';

  function uniqueSids(){
    const seen=new Set(), out=[];
    items.forEach(it=>{ if(!seen.has(it.sid)){ seen.add(it.sid); out.push(it.sid); } });
    return out;
  }
  function sidHasPicado(sid){ return items.some(it=>it.sid===sid && it.st==='picado'); }
  // excepciones a la regla general (nombre termina en a/á = femenino → "picada")
  const PICADO_WORD_OVERRIDE={coliflor:'picada', anana:'picado', nueces:'picadas', ciboulette:'picada'};
  function picadoWordFor(sid){
    if(PICADO_WORD_OVERRIDE[sid]) return PICADO_WORD_OVERRIDE[sid];
    const nm=((spriteById[sid]&&spriteById[sid].name)||sid).trim();
    return /[aá]$/i.test(nm) ? 'picada' : 'picado';
  }
  function rebuild(){
    const sids=uniqueSids();
    hasMuzza=sids.includes('muzzarella');
    const rest=sids.filter(s=>s!=='muzzarella');
    const prev=order.filter(s=>rest.includes(s));       // conserva orden manual
    const add=rest.filter(s=>!prev.includes(s));         // nuevos al final
    order=[...prev,...add];
    [...sids].forEach(s=>{ if(!meta[s]) meta[s]={include:true,label:(spriteById[s]&&spriteById[s].name)||s,showPicado:true}; });
    drizOrder = activeDrizzles.filter(id=>drizById(id));   // salsas activas → a la lista
    drizOrder.forEach(id=>{ const k='d:'+id; if(!meta[k]) meta[k]={include:true,label:(drizById(id)||{}).name||id}; });
    if(baseLabel==='') baseLabel=BASE_LABEL[curBase]||'';
  }

  // agrega "picado"/"picada" al final de la etiqueta (sin paréntesis) si corresponde
  function withPicado(sid,label){
    if(!label) return label;
    const m=meta[sid];
    if(!sidHasPicado(sid) || !m || m.showPicado===false) return label;
    if(/picad[oa]s?\b/i.test(label)) return label; // ya lo dice el nombre (ej. "Carne picada")
    return label+' '+picadoWordFor(sid);
  }

  // etiquetas finales, en orden: base, muzza, resto
  function listLabels(){
    const out=[];
    if(curBase!=='none' && baseInc && (baseLabel||'').trim()) out.push(baseLabel.trim());
    if(hasMuzza && meta['muzzarella'] && meta['muzzarella'].include) out.push(withPicado('muzzarella',(meta['muzzarella'].label||'Muzzarella').trim()));
    order.forEach(s=>{ if(meta[s] && meta[s].include && (meta[s].label||'').trim()) out.push(withPicado(s,meta[s].label.trim())); });
    drizOrder.forEach(id=>{ const m=meta['d:'+id]; if(m && m.include && (m.label||'').trim()) out.push(m.label.trim()); });
    return out;
  }

  // ---- UI de la lista ----
  function row(kind, sid){
    const it=document.createElement('div'); it.className='exp-item'+(kind!=='top'?' pin':'');
    const inc=document.createElement('input'); inc.type='checkbox'; inc.className='inc';
    const nm=document.createElement('input'); nm.className='nm'; nm.type='text'; nm.maxLength=40;
    if(kind==='base'){ inc.checked=baseInc; nm.value=baseLabel; nm.oninput=()=>{baseLabel=nm.value; draw();}; inc.onchange=()=>{baseInc=inc.checked; draw();}; }
    else { const m=meta[sid]; inc.checked=m.include; nm.value=m.label; nm.oninput=()=>{m.label=nm.value; draw();}; inc.onchange=()=>{m.include=inc.checked; draw();}; }
    const tag=document.createElement('span'); tag.className='tagp';
    tag.textContent = kind==='base'?'Base' : kind==='muzza'?'Queso' : '';
    it.appendChild(inc); it.appendChild(nm);
    if(tag.textContent) it.appendChild(tag);
    if(kind!=='base' && sidHasPicado(sid)){
      const m=meta[sid];
      const pic=document.createElement('button'); pic.type='button'; pic.className='picbtn'+(m.showPicado!==false?' on':'');
      pic.title=m.showPicado!==false?`Ocultar "${picadoWordFor(sid)}"`:`Mostrar "${picadoWordFor(sid)}"`;
      pic.textContent='🔪';
      pic.onclick=()=>{ m.showPicado = (m.showPicado===false) ? true : false; renderList(); draw(); };
      it.appendChild(pic);
    }
    if(kind==='top'){
      const i=order.indexOf(sid);
      const up=document.createElement('button'); up.className='mv'; up.textContent='â–²'; up.title='Subir';
      up.disabled=(i<=0); up.onclick=()=>{ if(i>0){ [order[i-1],order[i]]=[order[i],order[i-1]]; renderList(); draw(); } };
      const dn=document.createElement('button'); dn.className='mv'; dn.textContent='â–¼'; dn.title='Bajar';
      dn.disabled=(i>=order.length-1); dn.onclick=()=>{ if(i<order.length-1){ [order[i+1],order[i]]=[order[i],order[i+1]]; renderList(); draw(); } };
      it.appendChild(up); it.appendChild(dn);
    }
    return it;
  }
  // fila de salsa (drizzle): incluir + nombre editable, sin picado ni reordenar
  function rowDriz(id){
    const m=meta['d:'+id];
    const it=document.createElement('div'); it.className='exp-item pin';
    const inc=document.createElement('input'); inc.type='checkbox'; inc.className='inc'; inc.checked=m.include;
    inc.onchange=()=>{ m.include=inc.checked; draw(); };
    const nm=document.createElement('input'); nm.className='nm'; nm.type='text'; nm.maxLength=40; nm.value=m.label;
    nm.oninput=()=>{ m.label=nm.value; draw(); };
    const tag=document.createElement('span'); tag.className='tagp'; tag.textContent='Salsa';
    it.appendChild(inc); it.appendChild(nm); it.appendChild(tag);
    return it;
  }
  function renderList(){
    listEl.innerHTML='';
    const any = (curBase!=='none') || hasMuzza || order.length || drizOrder.length;
    if(!any){ const e=document.createElement('div'); e.className='exp-empty'; e.textContent='Agregá ingredientes a la pizza para armar la lista.'; listEl.appendChild(e); return; }
    if(curBase!=='none') listEl.appendChild(row('base'));
    if(hasMuzza) listEl.appendChild(row('muzza','muzzarella'));
    order.forEach(s=>listEl.appendChild(row('top',s)));
    drizOrder.forEach(id=>listEl.appendChild(rowDriz(id)));
  }

  // ---- render de la pizza (cuadrada, fondo transparente) ----
  function pizzaSquare(P){
    const pc=document.createElement('canvas'); pc.width=P; pc.height=P;
    const c=pc.getContext('2d'); c.imageSmoothingEnabled=false;
    // caja de dibujo con el aspecto del formato, centrada dentro del cuadrado
    const a=fmtAspect();
    const dW = a>=1 ? P : P*a;
    const dH = a>=1 ? P/a : P;
    const ox=(P-dW)/2, oy=(P-dH)/2;
    const cx=P/2, cy=P/2, R=Math.min(dW,dH)/2;
    if(baseImg.complete && baseImg.naturalWidth) c.drawImage(baseImg,ox,oy,dW,dH);
    const si=sauceInsetFor(), _db=doughBoxFor(), _dw=dW*(_db.x1-_db.x0), _dh=dH*(_db.y1-_db.y0);
    const rx=(_dw/2)*(1-2*si.x), ry=(_dh/2)*(1-2*si.y);
    paintBaseAll(c, cx, cy, rx, ry);
    items.slice().sort((a,b)=>a.z-b.z).forEach(it=>{
      const s=stateSprite(it); const img=imgFor(s.uri);
      const w=s.w*PX*scaleFor(it.sid)*fmtScale()*it.scl*(dW/REF), h=s.h*PX*scaleFor(it.sid)*fmtScale()*it.scl*(dW/REF);
      c.save(); c.globalAlpha=opacityOf(it.sid); c.translate(ox+it.fx*dW,oy+it.fy*dH); c.rotate(it.rot*Math.PI/180); c.scale(it.flip?-1:1,1);
      try{ c.drawImage(img,-w/2,-h/2,w,h); }catch(e){}
      c.restore();
    });
    try{ drawDrizzles(c, cx, cy, R, activeDrizzles); }catch(e){}
    return pc;
  }

  // ---- helpers de texto ----
  function wrapWords(c,text,maxW){
    const words=(text||'').split(/\s+/).filter(Boolean); const lines=[]; let cur='';
    words.forEach(w=>{ const t=cur?cur+' '+w:w; if(c.measureText(t).width>maxW && cur){ lines.push(cur); cur=w; } else cur=t; });
    if(cur) lines.push(cur); return lines.length?lines:[''];
  }
  function wrapDots(c,arr,maxW){
    const lines=[]; let cur='';
    arr.forEach(w=>{ const t=cur?cur+'  ·  '+w:w; if(c.measureText(t).width>maxW && cur){ lines.push(cur); cur=w; } else cur=t; });
    if(cur) lines.push(cur); return lines;
  }
  function roundRect(c,x,y,w,h,r){ c.beginPath(); c.moveTo(x+r,y); c.arcTo(x+w,y,x+w,y+h,r); c.arcTo(x+w,y+h,x,y+h,r); c.arcTo(x,y+h,x,y,r); c.arcTo(x,y,x+w,y,r); c.closePath(); }

  function drawRibbon(c,cx,y,w,h,text){
    const notch=h*0.30;
    c.save();
    c.beginPath();
    c.moveTo(cx-w/2, y);
    c.lineTo(cx+w/2, y);
    c.lineTo(cx+w/2 - notch, y+h/2);
    c.lineTo(cx+w/2, y+h);
    c.lineTo(cx-w/2, y+h);
    c.lineTo(cx-w/2 + notch, y+h/2);
    c.closePath();
    c.fillStyle='#CC1414'; c.fill();
    // keyline interna crema
    c.lineWidth=Math.max(2,h*0.045); c.strokeStyle='rgba(240,230,208,.8)';
    const pad=h*0.16, nn=Math.max(0,notch-pad*0.6);
    c.beginPath();
    c.moveTo(cx-w/2+pad, y+pad);
    c.lineTo(cx+w/2-pad, y+pad);
    c.lineTo(cx+w/2-pad - nn, y+h/2);
    c.lineTo(cx+w/2-pad, y+h-pad);
    c.lineTo(cx-w/2+pad, y+h-pad);
    c.lineTo(cx-w/2+pad + nn, y+h/2);
    c.closePath(); c.stroke();
    // texto
    c.fillStyle='#F5ECD6'; c.textAlign='center'; c.textBaseline='middle';
    let fs=h*0.46; c.font=fs+'px '+FF;
    const maxTW=w*0.72;
    while(c.measureText(text).width>maxTW && fs>10){ fs-=1; c.font=fs+'px '+FF; }
    c.fillText(text, cx, y+h/2 + h*0.03);
    c.restore();
  }

  // ---- render completo ----
  function draw(){
    const f=FORMATS[fmt], W=f.w, H=f.h;
    cv.width=W; cv.height=H;
    const c=cv.getContext('2d');
    // fondo crema con textura sutil
    c.fillStyle='#F0E6D0'; c.fillRect(0,0,W,H);
    const g=c.createRadialGradient(W*0.78,H*0.05,10, W*0.78,H*0.05, W*0.9);
    g.addColorStop(0,'rgba(212,180,131,.32)'); g.addColorStop(1,'rgba(212,180,131,0)');
    c.fillStyle=g; c.fillRect(0,0,W,H);

    const margin=Math.round(W*0.07);
    const contentW=W-2*margin;
    const gap=Math.round(W*0.038);
    const ribbonShow = ribOn.checked && (ribTxt.value||'').trim();
    const name=(nameInput.value||'').trim();
    const labels=listLabels();

    // medidas ribbon
    const rh = ribbonShow ? Math.round(W*0.092) : 0;

    // subtitulo de estilo (solo si NO es napolitana)
    const styleSub = (curFmt!=='napolitana') ? ('Pizza estilo '+fmtDef().name) : '';
    let subFs=0, subH=0;
    if(styleSub){ subFs=Math.round(W*0.052); subH=Math.round(subFs*1.25); }

    // medidas nombre
    let nameLines=[], nameFs=0, nameH=0, underH=0;
    if(name){
      nameFs=Math.round(W*(fmt==='story'?0.115:0.10));
      const minFs=Math.round(W*0.058);
      c.font=nameFs+'px '+FF; nameLines=wrapWords(c,name,contentW);
      while(nameLines.length>2 && nameFs>minFs){ nameFs-=2; c.font=nameFs+'px '+FF; nameLines=wrapWords(c,name,contentW); }
      underH=Math.round(nameFs*0.34);
      nameH=nameLines.length*Math.round(nameFs*1.04)+underH;
    }

    // medidas caja ingredientes
    let ingFs=Math.round(W*(fmt==='story'?0.036:0.034));
    const boxPadX=Math.round(W*0.055), boxPadY=Math.round(W*0.042);
    let ingLines=[], boxH=0, lineH=0;
    if(labels.length){
      c.font=ingFs+'px '+FF;
      ingLines=wrapDots(c,labels,contentW-2*boxPadX);
      const minIf=Math.round(W*0.026);
      while(ingLines.length>(fmt==='feed'?3:6) && ingFs>minIf){ ingFs-=1; c.font=ingFs+'px '+FF; ingLines=wrapDots(c,labels,contentW-2*boxPadX); }
      lineH=Math.round(ingFs*1.4);
      boxH=ingLines.length*lineH + 2*boxPadY;
    }

    // tamaño pizza
    const nBlocks=(ribbonShow?1:0)+(name?1:0)+(labels.length?1:0);
    const used=rh+nameH+boxH+nBlocks*gap;
    let P=Math.min(contentW, H-2*margin-used);
    P=Math.max(P, Math.round(W*0.34));

    // centrado vertical del stack
    let stackH = P;
    if(ribbonShow) stackH+=rh+gap;
    if(styleSub) stackH+=subH+Math.round(gap*0.4);
    if(name) stackH+=nameH+gap;
    if(labels.length) stackH+=boxH+gap;
    let y=Math.max(margin, Math.round((H-stackH)/2));
    const cx=W/2;

    // ribbon
    if(ribbonShow){ drawRibbon(c,cx,y,Math.round(contentW*0.92),rh,(ribTxt.value||'').trim()); y+=rh+gap; }

    // pizza
    const pc=pizzaSquare(Math.round(P));
    c.drawImage(pc,Math.round(cx-P/2),Math.round(y),Math.round(P),Math.round(P));
    y+=P+gap;

    // subtitulo estilo
    if(styleSub){
      c.textAlign='center'; c.textBaseline='top'; c.fillStyle='#8a5a2a';
      c.font='italic '+subFs+'px '+FF;
      c.fillText(styleSub, cx, y);
      y+=subH+Math.round(gap*0.4);
    }

    // nombre (H1)
    if(name){
      c.textAlign='center'; c.textBaseline='top'; c.fillStyle='#2b1a0a';
      c.font=nameFs+'px '+FF;
      const lh=Math.round(nameFs*1.04);
      nameLines.forEach((ln,i)=>c.fillText(ln,cx,y+i*lh));
      const uy=y+nameLines.length*lh+Math.round(underH*0.34);
      const uw=Math.min(contentW*0.5, Math.round(W*0.16));
      c.fillStyle='#CC1414'; roundRect(c,cx-uw/2,uy,uw,Math.max(3,Math.round(W*0.006)),Math.round(W*0.004)); c.fill();
      y+=nameH+gap;
    }

    // caja ingredientes (H1 → lista)
    if(labels.length){
      const bx=margin, bw=contentW, by=y, bh=boxH;
      roundRect(c,bx,by,bw,bh,Math.round(W*0.02));
      c.fillStyle='#F8F6F2'; c.fill();
      c.lineWidth=Math.max(2,Math.round(W*0.0035)); c.strokeStyle='rgba(184,149,90,.55)'; c.stroke();
      c.fillStyle='#3a2411'; c.textAlign='center'; c.textBaseline='middle'; c.font=ingFs+'px '+FF;
      const total=ingLines.length*lineH;
      let ty=by+ (bh-total)/2 + lineH/2;
      ingLines.forEach(ln=>{ c.fillText(ln,cx,ty); ty+=lineH; });
    }
  }

  // ---- descarga ----
  function slug(){
    const n=(nameInput.value||'').trim();
    return n? n.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'') : '';
  }
  async function ensureImgs(){
    const arr=[baseImg]; items.forEach(it=>{ arr.push(imgFor(stateSprite(it).uri)); });
    await Promise.all(arr.map(im=>{ if(im.complete && im.naturalWidth) return; return (im.decode?im.decode().catch(()=>{}):new Promise(r=>{im.onload=im.onerror=r;})); }));
  }
  async function download(){
    await ensureImgs(); if(document.fonts && document.fonts.ready){ try{await document.fonts.ready;}catch(e){} }
    draw();
    cv.toBlob(b=>{
      const a=document.createElement('a'); a.href=URL.createObjectURL(b);
            const s=slug(); const ext=(expExt||'png');
      a.download=(s?('arrabbiata-'+s):'arrabbiata-pizza')+'-'+fmt+'.'+ext;
      const mime = (ext==='jpg') ? 'image/jpeg' : 'image/png';
      if(_isIOS()){ _showSaveSheet(cv.toDataURL('image/png'), a.download); } else { a.click(); }
      setTimeout(()=>URL.revokeObjectURL(a.href),1200);
    }, (expExt==='jpg'?'image/jpeg':'image/png'));
    toast('PNG '+fmt+' exportado');
  }
  async function downloadPizza(){
    await ensureImgs();
    const P=1200, pc=pizzaSquare(P);
    pc.toBlob(b=>{
      const a=document.createElement('a'); a.href=URL.createObjectURL(b);
      const s=slug(); a.download=(s?('pizza-'+s):'pizza-arrabbiata')+'.png';
      if(_isIOS()){ _showSaveSheet(pc.toDataURL('image/png'), a.download); } else { a.click(); }
      setTimeout(()=>URL.revokeObjectURL(a.href),1200);
    }, (expExt==='jpg'?'image/jpeg':'image/png'));
    toast('Pizza exportada');
  }

  // ---- abrir / cerrar ----
  function open(){
    nameInput.value=pizzaNameEl?pizzaNameEl.value:'';
    baseLabel=''; rebuild();
    if(baseLabel==='') baseLabel=BASE_LABEL[curBase]||'';
    renderList(); draw();
    mask.classList.add('on');
  }
  function close(){ mask.classList.remove('on'); }

  // sincronizar nombre con la topbar
  nameInput.addEventListener('input',()=>{ if(pizzaNameEl) pizzaNameEl.value=nameInput.value; draw(); });
  ribOn.addEventListener('change',draw);
  ribTxt.addEventListener('input',draw);
  document.getElementById('expClose').addEventListener('click',close);
  mask.addEventListener('click',e=>{ if(e.target===mask) close(); });
  window.addEventListener('keydown',e=>{ if(e.key==='Escape' && mask.classList.contains('on')){ e.stopPropagation(); close(); } },true);
  document.getElementById('expFmt').addEventListener('click',e=>{
    const b=e.target.closest('button[data-fmt]'); if(!b) return;
    fmt=b.dataset.fmt; [...e.currentTarget.children].forEach(x=>x.classList.toggle('sel',x===b)); draw();
  });
  document.getElementById('expDo').addEventListener('click',download);
  document.getElementById('expDoPizza').addEventListener('click',downloadPizza);
  // ---- formato archivo descarga PNG / JPG y compartir ----
  let expExt = 'png';
  const expFileFmt = document.getElementById('expFileFmt');
  if(expFileFmt){
    expFileFmt.addEventListener('click', e => {
      const b = e.target.closest('button[data-ext]'); if(!b) return;
      expExt = b.dataset.ext;
      [...expFileFmt.children].forEach(x => x.classList.toggle('sel', x === b));
      const lbl = document.getElementById('expDoLbl');
      if(lbl) lbl.textContent = 'Descargar ' + expExt.toUpperCase();
    });
  }

  async function shareWa(){
    const name = (nameInput.value || (pizzaNameEl?pizzaNameEl.value:'') || 'Mi pizza').trim();
    const txt = '¡Mirá la pizza que armé en Arrabbiata! 🍕 ' + name;
    await download();
    toast('Imagen descargada · abriendo WhatsApp');
    setTimeout(() => {
      window.open('https://wa.me/?text=' + encodeURIComponent(txt), '_blank');
    }, 400);
  }

  async function shareStory(){
    const name = (nameInput.value || (pizzaNameEl?pizzaNameEl.value:'') || 'Mi pizza').trim();
    await ensureImgs();
    if(document.fonts && document.fonts.ready){ try{await document.fonts.ready;}catch(e){} }
    draw();
    if(navigator.share && cv && cv.toBlob){
      try {
        cv.toBlob(async blob => {
          const s = slug();
          const fname = (s?('arrabbiata-'+s):'arrabbiata-pizza')+'-'+fmt+'.png';
          const file = new File([blob], fname, { type: 'image/png' });
          if(navigator.canShare && navigator.canShare({ files: [file] })){
            await navigator.share({
              title: name,
              text: 'Pizza armada en Arrabbiata',
              files: [file]
            });
            toast('¡Compartido!');
            return;
          }
          await download();
          toast('Imagen descargada para subir a tu historia');
        }, 'image/png');
        return;
      } catch(e){}
    }
    await download();
    toast('Imagen descargada para compartir');
  }

  const btnShareWa = document.getElementById('expShareWa');
  if(btnShareWa) btnShareWa.addEventListener('click', shareWa);

  const btnShareStory = document.getElementById('expShareStory');
  if(btnShareStory) btnShareStory.addEventListener('click', shareStory);

  // reemplazar el botón Exportar de la topbar para abrir este panel
  const oldBtn=document.getElementById('btnExport');
  const nb=oldBtn.cloneNode(true); oldBtn.parentNode.replaceChild(nb,oldBtn);
  nb.addEventListener('click',open);

  // exponer por si hace falta
  window.__openExport=open;
  window.__pizzaSquare=pizzaSquare;
})();
</script>


<!-- ============ Galería de pizzas ============ -->
<div class="galmask" id="galMask">
  <div class="galwrap">
    <div class="h">
      <h3>Galería de pizzas</h3>
      <span class="sp"></span>
      <button id="galRefresh" title="Actualizar">↻</button>
      <button class="x" id="galClose" title="Cerrar">✕</button>
    </div>
    <div class="galgrid" id="galGrid"></div>
  </div>
</div>


<script>
/* ============ Galería + guardado de pizzas (servidor) ============ */
(function(){
  "use strict";
  const API_URL='api.php';
  let currentPizzaId='';
  const mask=document.getElementById('galMask');
  const grid=document.getElementById('galGrid');

  function tok(){ try{ return localStorage.getItem('rrbb_api_token')||''; }catch(e){ return ''; } }
  function setTok(t){ try{ localStorage.setItem('rrbb_api_token', t||''); }catch(e){} }
  async function apiGet(qs){ try{ const r=await fetch(API_URL+'?action='+qs); return await r.json(); }catch(e){ return null; } }
  async function apiPost(qs, body){
    let token=tok();
    for(let i=0;i<2;i++){
      let r;
      try{ r=await fetch(API_URL+'?action='+qs,{method:'POST',headers:{'Content-Type':'application/json','X-Auth-Token':token},body:JSON.stringify(body||{})}); }
      catch(e){ toast('Sin conexión con el servidor'); return null; }
      if(r.status===401){ const t=prompt('Token del servidor (config.php):', token); if(t==null) return null; token=t.trim(); setTok(token); continue; }
      let d=null; try{ d=await r.json(); }catch(e){}
      if(r.ok && d && d.ok) return d;
      toast('Error: '+((d&&d.error)||('HTTP '+r.status))); return d;
    }
    return null;
  }

  // ---- serializar / guardar ----
  function serialize(){
    const name=(document.getElementById('pizzaName').value||'').trim()||'Pizza';
    const its=items.slice().sort((a,b)=>a.z-b.z).map(it=>({sid:it.sid, fx:+it.fx.toFixed(4), fy:+it.fy.toFixed(4), rot:+(+it.rot).toFixed(2), scl:it.scl, flip:!!it.flip, st:it.st}));
    let thumb=''; try{ thumb=window.__pizzaSquare(240).toDataURL('image/png'); }catch(e){}
    return {schema:1, id:currentPizzaId||'', name, base:curBase, fmt:curFmt, items:its, drizzles:activeDrizzles.slice(), thumb};
  }
  async function savePizza(){
    if(!items.length){ toast('La pizza está vacía'); return; }
    const r=await apiPost('save-pizza', serialize());
    if(r && r.ok){ currentPizzaId=r.id; toast('Pizza guardada en la galería'); }
  }

  // ---- cargar en el editor ----
  function loadPizza(p){
    if(!p){ toast('No pude abrir la pizza'); return; }
    snapshot();
    items.length=0; layer.innerHTML=''; select(null);
    setBase(p.base||'tomate');
    setFmt(p.fmt||'napolitana', true);
    document.getElementById('pizzaName').value=p.name||'';
    zTop=0;
    const missing=[];
    (p.items||[]).forEach(s=>{
      if(!spriteById[s.sid]){ missing.push(s.sid); return; }
      items.push({uid:Math.random().toString(36).slice(2), sid:s.sid, fx:s.fx, fy:s.fy, st:s.st||'entero', rot:s.rot||0, scl:s.scl||1, flip:!!s.flip, z:++zTop});
    });
    renderAll();
    activeDrizzles.length=0; (p.drizzles||[]).forEach(id=>{ if(drizById(id)) activeDrizzles.push(id); });
    document.querySelectorAll('#grid .chip[data-driz]').forEach(x=>x.classList.toggle('active', activeDrizzles.includes(x.dataset.driz)));
    renderDrizzleStage();
    currentPizzaId=p.id||'';
    if(missing.length) toast('Cargada. Ojo: '+missing.length+' ingrediente(s) ya no están en la biblioteca y se omitieron');
    else toast('Pizza cargada');
  }

  // ---- galería ----
  function fmtDate(ts){ const d=new Date((ts||0)*1000); return isNaN(d.getTime())?'':d.toLocaleDateString(); }
  function render(list){
    grid.innerHTML='';
    if(!list.length){ grid.innerHTML='<div class="gal-empty">Todavía no guardaste ninguna pizza.<br>Armá una y tocá “Guardar pizza”.</div>'; return; }
    list.forEach(p=>{
      const c=document.createElement('div'); c.className='gal-card';
      c.innerHTML='<div class="gal-thumb">'+(p.thumb?('<img alt="">'):'🍕')+'</div>'+
        '<div class="gal-meta"><div class="gal-name"></div><div class="gal-sub"></div></div>'+
        '<div class="gal-acts"><button class="gbtn open">Abrir</button><button class="gbtn del">Borrar</button></div>';
      if(p.thumb) c.querySelector('.gal-thumb img').src=p.thumb;
      c.querySelector('.gal-name').textContent=p.name||'(sin nombre)';
      c.querySelector('.gal-sub').textContent=(p.count||0)+' ingr · '+fmtDate(p.updatedAt);
      c.querySelector('.open').onclick=()=>openOne(p.id);
      c.querySelector('.del').onclick=()=>delOne(p.id, p.name||'(sin nombre)');
      grid.appendChild(c);
    });
  }
  async function openGallery(){
    mask.classList.add('on'); grid.innerHTML='<div class="gal-empty">Cargando…</div>';
    const r=await apiGet('list-pizzas');
    if(!r || !r.ok){ grid.innerHTML='<div class="gal-empty">No pude cargar la galería.<br>¿Subiste api.php al servidor?</div>'; return; }
    render(r.pizzas||[]);
  }
  function close(){ mask.classList.remove('on'); }
  async function openOne(id){
    let r;
    try{ r = await apiGet('get-pizza&id='+encodeURIComponent(id)); }
    catch(e){ toast('No pude abrir: error de red'); console.error('get-pizza red', e); return; }
    const p = r && (r.pizza || r.data || (Array.isArray(r.items)? r : null));
    if(!p){ toast('No pude abrir: '+((r && r.error) || 'el servidor no devolvió la pizza')); console.warn('get-pizza sin pizza', r); return; }
    try{ loadPizza(p); close(); }
    catch(e){ toast('No pude abrir: '+((e && e.message) || e)); console.error('loadPizza falló', e); }
  }
  async function delOne(id,name){ if(!confirm('¿Borrar “'+name+'”? No se puede deshacer.')) return; const r=await apiPost('delete-pizza&id='+encodeURIComponent(id),{id:id}); if(r && r.ok){ openGallery(); } }

  // ---- wiring ----
  const bSave=document.getElementById('btnSavePizza'); if(bSave) bSave.onclick=savePizza;
  const bGal=document.getElementById('btnGallery');   if(bGal) bGal.onclick=openGallery;
  document.getElementById('galClose').addEventListener('click',close);
  document.getElementById('galRefresh').addEventListener('click',openGallery);
  mask.addEventListener('click',e=>{ if(e.target===mask) close(); });
  window.addEventListener('keydown',e=>{ if(e.key==='Escape' && mask.classList.contains('on')){ e.stopPropagation(); close(); } },true);
  // al limpiar la pizza, la próxima que se guarde es nueva
  const bClear=document.getElementById('btnClear'); if(bClear) bClear.addEventListener('click',()=>{ currentPizzaId=''; });
})();
</script>


<script>
/* ====== cargar-en-el-puntero + estampar (Pizza Tycoon style) ====== */
(function(){
  "use strict";
  const loadBar=document.getElementById('loadBar');
  const loadState=document.getElementById('loadState');
  const loadThumb=document.getElementById('loadThumb');
  const loadName=document.getElementById('loadName');
  const ghost=document.getElementById('ghost');
  const ghostImg=ghost?ghost.querySelector('img'):null;

  function stampSprite(){ return stateSprite({sid:activeSid, st:placeState}); }

  window.toggleLoad=function(sid){ if(placing && sid===activeSid) unloadIngredient(); else loadIngredient(sid); };
  window.loadIngredient=function(sid){
    if(!spriteById[sid]) return;
    activeSid=sid; placing=true;
    const av=statesOf(sid); if(!av.includes(placeState)) placeState='entero';
    select(null); markActiveChip(); updateLoadBar();
    stage.classList.add('is-placing');
    if(COARSE){ document.body.classList.add('tray-min'); const tt=document.getElementById('trayToggle'); if(tt) tt.textContent='â–´'; }
    toast('Cargado: '+spriteById[sid].name+' — tocá la pizza');
  };
  window.unloadIngredient=function(){
    placing=false; stage.classList.remove('is-placing'); hideGhost(); markActiveChip(); updateLoadBar();
  };
  window.placeAt=function(clientX,clientY){
    if(!placing) return;
    const r=stage.getBoundingClientRect();
    if(!insideCircle(clientX,clientY,r)) return;
    addItem(activeSid,(clientX-r.left)/r.width,(clientY-r.top)/r.height,{st:placeState,silent:true});
  };
  function updateLoadBar(){
    if(!placing){ loadBar.classList.remove('show'); return; }
    const s=spriteById[activeSid]; const sp=stampSprite();
    loadThumb.src=sp.uri; loadName.textContent=s.name;
    const av=statesOf(activeSid);
    loadState.style.display = av.length>1 ? '' : 'none';
    loadState.querySelectorAll('[data-st]').forEach(b=>{
      const st=b.dataset.st, has=av.includes(st);
      b.style.display=has?'':'none'; b.disabled=!has; b.classList.toggle('sel', st===placeState);
    });
    loadBar.classList.add('show');
  }
  function setPlaceState(st){ if(!statesOf(activeSid).includes(st)) return; placeState=st; updateLoadBar(); refreshGhost(); }
  loadState.querySelectorAll('[data-st]').forEach(b=>b.addEventListener('click',()=>setPlaceState(b.dataset.st)));
  document.getElementById('loadClear').addEventListener('click',unloadIngredient);

  // ---- fantasma que sigue al puntero (solo desktop) ----
  function hideGhost(){ if(ghost) ghost.style.display='none'; }
  function refreshGhost(){ if(ghost && ghost.style.display==='block' && placing && ghostImg){ ghostImg.src=stampSprite().uri; } }
  window.hideGhost=hideGhost;
  if(!COARSE && ghost){
    stage.addEventListener('pointermove',e=>{
      if(!placing){ hideGhost(); return; }
      const r=stage.getBoundingClientRect();
      const sp=stampSprite();
      const scl=(spriteById[activeSid]&&spriteById[activeSid].scl)||1;   // misma escala propia que aplica addItem
      const w=sp.w*PX*scaleFor(activeSid)*fmtScale()*scl*(stageSize()/REF), h=sp.h*PX*scaleFor(activeSid)*fmtScale()*scl*(stageSize()/REF);
      ghostImg.src=sp.uri;
      ghost.style.width=w+'px'; ghost.style.height=h+'px';
      ghost.style.left=(e.clientX-r.left)+'px'; ghost.style.top=(e.clientY-r.top)+'px';
      ghost.style.display='block';
    });
    stage.addEventListener('pointerleave',hideGhost);
  }
})();
</script>

<!-- ====== DEBUG DE ALINEACION (solo con ?debug=1) ====== -->
<script>
(function(){
  if(!/(?:[?&]debug=1|#debug)/.test(location.search+location.hash)) return;
  const stage=document.getElementById('stage');
  const baseImg=document.getElementById('baseImg');
  const sauce=document.getElementById('sauce');
  if(!stage||!baseImg||!sauce) return;
  const DB={napolitana:{x0:0,y0:0,x1:1,y1:1},ny:{x0:0,y0:0,x1:1,y1:1},
            molde:{x0:0,y0:0.07,x1:1,y1:0.93},plancha:{x0:0,y0:0,x1:1,y1:1}};
  function contain(){
    const r=stage.getBoundingClientRect();
    const nw=baseImg.naturalWidth, nh=baseImg.naturalHeight;
    if(!nw||!nh) return {left:r.left,top:r.top,width:r.width,height:r.height,nw,nh,stageW:r.width,stageH:r.height,stageTop:r.top};
    const s=Math.min(r.width/nw, r.height/nh), w=nw*s, h=nh*s;
    return {left:r.left+(r.width-w)/2, top:r.top+(r.height-h)/2, width:w, height:h, nw, nh, stageW:r.width, stageH:r.height, stageTop:r.top};
  }
  function box(color,dash){const d=document.createElement('div');
    d.style.cssText='position:fixed;z-index:9999;pointer-events:none;box-sizing:border-box;border:2px '+(dash?'dashed':'solid')+' '+color;
    document.body.appendChild(d);return d;}
  const imgBox=box('#00e03c'),doughBox=box('#ff2ccf',true),sauceBox=box('#1e90ff'),stageBox=box('#ffd000',true);
  const readout=document.createElement('div');
  readout.style.cssText='position:fixed;left:8px;top:64px;z-index:10000;background:rgba(0,0,0,.82);color:#fff;'+
    'font:12px/1.35 monospace;padding:8px 10px;border-radius:8px;max-width:94vw;white-space:pre;pointer-events:none';
  document.body.appendChild(readout);
  function put(el,l,t,w,h){el.style.left=l+'px';el.style.top=t+'px';el.style.width=w+'px';el.style.height=h+'px';}
  function upd(){
    const ir=contain(), db=DB[stage.getAttribute('data-fmt')]||{x0:0,y0:0,x1:1,y1:1};
    put(imgBox,ir.left,ir.top,ir.width,ir.height);
    const dl=ir.left+db.x0*ir.width, dt=ir.top+db.y0*ir.height, dw=(db.x1-db.x0)*ir.width, dh=(db.y1-db.y0)*ir.height;
    put(doughBox,dl,dt,dw,dh);
    const sr=sauce.getBoundingClientRect(); put(sauceBox,sr.left,sr.top,sr.width,sr.height);
    const rr=stage.getBoundingClientRect(); put(stageBox,rr.left,rr.top,rr.width,rr.height);
    readout.textContent=
      'fmt: '+stage.getAttribute('data-fmt')+'   viewport '+innerWidth+'x'+innerHeight+'\n'+
      'PNG '+ir.nw+'x'+ir.nh+' (ar '+(ir.nw/ir.nh).toFixed(3)+')  stage '+Math.round(ir.stageW)+'x'+Math.round(ir.stageH)+' top='+Math.round(ir.stageTop)+'\n'+
      (ir.stageTop<0?'*** STAGE RECORTADO ARRIBA ('+Math.round(-ir.stageTop)+'px fuera) ***\n':'')+
      'imagen '+Math.round(ir.width)+'x'+Math.round(ir.height)+'  '+(Math.abs(ir.height-ir.stageH)<1?'sin letterbox':'CON letterbox '+Math.round((ir.stageH-ir.height)/2)+'px')+'\n'+
      'amarillo=stage verde=imagen magenta=masa azul=salsa';
  }
  const tick=()=>{upd();requestAnimationFrame(tick);};
  if(baseImg.complete) tick(); else baseImg.addEventListener('load',tick);
})();
</script>

</body>
